def main():
    with open(DRAFT) as f:
        d = json.load(f)
    added = []
    for s in SUBJ:
        if not any(s["codes"][0] in (x.get("codes") or []) for x in d["subjects"]):
            d["subjects"].append(s)
            added.append(s["codes"][0])
    if not d.get("non_subject_rows"):
        d["non_subject_rows"] = NSR
    for q in DOC_QUIRKS:
        if q not in d.get("quirks", []):
            d.setdefault("quirks", []).append(q)
    with open(DRAFT, "w") as f:
        json.dump(d, f, indent=1, ensure_ascii=False)
    print("p3 added:", added)
    print("FINAL D06 subjects:", len(d["subjects"]), "nsr:", len(d["non_subject_rows"]), "quirks:", len(d["quirks"]))
    print("codes:", sorted({c for s in d["subjects"] for c in s.get("codes", [])}))

if __name__ == "__main__":
    main()
